let current=samples[0],view='basics',stage='overview',filter='全部场景',search='',outcome='all',run=null,replay=null,formDraft=null;
const footer=`<footer class="page-footer"><span>${icon('flask')}交互演示 · 尚未连接真实模型 · 数值不能用于性能判断</span><a href="https://docs.typesafe.ai/introduction" target="_blank" rel="noreferrer">Jev 官方文档 ↗</a></footer>`;
